import json,subprocess,sys
T="08e9ce940e464e818b12108f6075d5bc1f50473c0afc435a95e4e0a329c2453d"
def get(u):
    return json.loads(subprocess.run(["curl","-s",u,"-H","Authorization: Bearer "+T],capture_output=True,text=True).stdout)
for gid in sys.argv[1:]:
    e=get(f"https://sentry.obico.io/api/0/issues/{gid}/events/latest/")
    json.dump(e,open(f"ev_{gid}.json","w"))
    tags={t['key']:t['value'] for t in e.get('tags',[])}
    print(f"\n######## {gid} {e.get('title')} | {e.get('dateCreated')}")
    print("tags:",{k:tags[k] for k in tags if k in('release','environment','os','os.name','device','browser','url','server_name','transaction','user','level','handled','mechanism','app.device','runtime','printer_id')})
    u=e.get('user'); print("user:",u and {k:u.get(k) for k in('id','username','ip_address','email')})
    for en in e.get('entries',[]):
        t=en['type']
        if t=='exception':
            for v in en['data']['values']:
                print("EXC",v.get('type'),":",(v.get('value') or '')[:400])
                fr=(v.get('stacktrace') or {}).get('frames') or []
                for f in fr[-14:]:
                    print("   ",'*' if f.get('inApp') else ' ',f.get('filename') or f.get('module'),f.get('lineNo'),f.get('function'),"|",(f.get('context') and [c[1] for c in f['context'] if c[0]==f.get('lineNo')] or [''])[0][:120] if f.get('context') else '')
        elif t=='request':
            d=en['data']; print("REQ",d.get('method'),d.get('url'),"q=",str(d.get('query'))[:200]); 
            h=dict(d.get('headers') or []); print("   hdr:",{k:h[k] for k in h if k.lower() in('user-agent','host','x-forwarded-for','origin','referer')})
        elif t=='message':
            print("MSG",str(en['data'].get('formatted'))[:300])
        elif t=='breadcrumbs':
            vals=en['data']['values'][-8:]
            for b in vals: print("  bc",b.get('timestamp','')[:19],b.get('category'),str(b.get('message') or b.get('data'))[:160])
EOF
