commit 635edd037f0dabd59ee99c0df968d66ca79ab3fc
Author: Kenneth Jiang <kenneth.jiang@gmail.com>
Date:   Tue Nov 24 15:50:46 2026 -0800

    Printer list no longer crashes after rotating a webcam with no primary camera

    A printer with several webcams and none marked primary has no primary
    webcam. Once the user rotated a webcam in full screen, the app saved a
    rotation for that printer, and the printer list's row then read
    primaryWebcam.name on undefined and crashed (Sentry OBICO-MOBILE-21A,
    PrinterItem.js:48:125). The row now reads primaryWebcam?.name and falls
    back to no rotation.

    The new Jest test renders the real row with a redux store, saves a
    rotation, and failed with the same TypeError before this change.

diff --git a/src/screens/PrinterList/PrinterItem.js b/src/screens/PrinterList/PrinterItem.js
index eacbace3..e40a90d5 100644
--- a/src/screens/PrinterList/PrinterItem.js
+++ b/src/screens/PrinterList/PrinterItem.js
@@ -45,7 +45,7 @@ const PrinterItem = (props) => {
     }
   });

-  const webcamUserRotationDeg = useSelector((state) => state.preferences?.webcamOpts?.[printerId.toString()]?.[primaryWebcam.name]?.userRotationDeg || 0);
+  const webcamUserRotationDeg = useSelector((state) => state.preferences?.webcamOpts?.[printerId.toString()]?.[primaryWebcam?.name]?.userRotationDeg || 0);

   const isFocused = useIsFocused();
   const thumbnailViewSize = width < height ? width : height;
diff --git a/src/screens/PrinterList/__tests__/PrinterItem-test.js b/src/screens/PrinterList/__tests__/PrinterItem-test.js
new file mode 100644
index 00000000..b2b24ab4
--- /dev/null
+++ b/src/screens/PrinterList/__tests__/PrinterItem-test.js
@@ -0,0 +1,51 @@
+/* eslint-env jest */
+import React from 'react';
+import renderer, {act} from 'react-test-renderer';
+import {Provider} from 'react-redux';
+import {createStore} from 'redux';
+
+// The real components pull in native modules (video, navigation, native-base) that jest cannot load.
+jest.mock('../../../components/WebCamView/WebCamView', () => () => null);
+jest.mock('@react-navigation/native', () => ({useIsFocused: () => true}));
+jest.mock('react-native-vector-icons/FontAwesome5', () => () => null);
+jest.mock('../../../hooks/useColors', () => () => ({color: () => '#000'}));
+jest.mock('../../../SyndicateContext', () => ({useSyndicate: () => ({syndicate: 'base'})}));
+jest.mock('react-native-device-time-format', () => ({is24HourFormat: () => Promise.resolve(false)}));
+jest.mock('native-base', () => {
+  const {View, Text} = jest.requireActual('react-native');
+  return {Heading: Text, View, Text, Progress: View, Icon: View, theme: {colors: {}, space: {'1': 4, '2': 8, '3': 12, '4': 16}}};
+});
+
+// PrinterItem.js reads Platform without importing it; give the test the same global the app sees.
+global.Platform = jest.requireActual('react-native').Platform;
+
+import PrinterItem from '../PrinterItem';
+
+const SAVE_ROTATION = 'SAVE_ROTATION';
+const printer = {
+  id: 1,
+  name: 'p',
+  status: {state: {text: 'Operational'}},
+  derivedStatus: {isOffline: false, isDisconnected: false, isActive: false, isWatching: false},
+  normalized_p: 0,
+  // Two webcams and neither is marked primary, so the row has no primary webcam.
+  settings: {webcams: [{name: 'a'}, {name: 'b'}]},
+};
+const reducer = (state, action) => action.type === SAVE_ROTATION
+  ? {...state, preferences: {webcamOpts: {'1': {a: {userRotationDeg: 90}}}}}
+  : state;
+
+describe('PrinterItem', () => {
+  it('keeps rendering after a webcam rotation is saved for a printer with no primary webcam', () => {
+    const store = createStore(reducer, {printers: [printer], preferences: {}});
+    let tree;
+    act(() => {
+      tree = renderer.create(<Provider store={store}><PrinterItem printerId={1} /></Provider>);
+    });
+    // What rotating the webcam in full screen does: it saves webcamOpts for this printer.
+    act(() => {
+      store.dispatch({type: SAVE_ROTATION});
+    });
+    expect(tree.toJSON()).toBeTruthy();
+  });
+});

