import FontAwesome5 from 'react-native-vector-icons/FontAwesome5';
import {P_VALUE_WARNING, P_VALUE_FAILURE} from '../../globals/constants';
import {progressInPct, humanizedDuration, timeFromNow,} from '../../libs/formatter';
import useColors from '../../hooks/useColors';
import { useSelector } from 'react-redux';
import { useSyndicate } from '@/SyndicateContext';
import { t,Trans } from '@lingui/macro';

const {width, height} = Dimensions.get('window');

const PrinterItem = (props) => {
  const {printerId} = props;

  const printerName = useSelector(state =>
    _.find(state.printers, (p) => p.id === printerId).name);

  // excluding _ts + using memoization (_.isEqual) here prevents `printerStatus` to be frequently
  // updated and as a result saves this component from bunch of unnecessary re-renderings
  const printerStatus = useSelector(state => {
    const status = _.find(state.printers, (p) => p.id === printerId).status;
    return { ...status, _ts: null };
  }, _.isEqual);

  const progress = printerStatus?.progress?.completion || 0;
  const printTimeLeft = printerStatus?.progress?.printTimeLeft;
  const statusText = printerStatus?.state?.text;

  const derivedStatus = useSelector(state =>
    _.find(state.printers, (p) => p.id === printerId).derivedStatus);

  const normalizedP = useSelector(state => _.find(state.printers, (p) => p.id === printerId).normalized_p || 0);

  const primaryWebcam = useSelector( (state) => {
    const webcams = _.filter(state.printers, {id: printerId})[0]?.settings?.webcams;
    if (webcams && webcams.length === 1) {
      return webcams[0];
    } else {
      return _.find(webcams, {is_primary_camera: true});
    }
  });

  const webcamUserRotationDeg = useSelector((state) => state.preferences?.webcamOpts?.[printerId.toString()]?.[primaryWebcam?.name]?.userRotationDeg || 0);

  const isFocused = useIsFocused();

