import _ from 'lodash';
import React, {useEffect, useState, useCallback} from 'react';
import {useSelector, useDispatch} from 'react-redux';
import { StyleSheet, BackHandler } from 'react-native';
import {useRoute, useNavigation} from '@react-navigation/native';
import { View, Box } from 'native-base';
import Orientation, {useDeviceOrientationChange} from 'react-native-orientation-locker';
import { activateKeepAwake, deactivateKeepAwake} from '@sayem314/react-native-keep-awake';

import * as actions from '../../redux/actions';
import WebCamView from '../../components/WebCamView/WebCamView';
import ZoomView from '../../components/ZoomView/ZoomView';
import ContextMenu from '../../components/WebCamView/ContextMenu';
import WebCamFullscreenOverlay from './WebCamFullscreenOverlay';
import { useIsFocused } from '@react-navigation/native';

const FullScreenWebCam = (props) => {
  const dispatch = useDispatch();
  const route = useRoute();
  const navigation = useNavigation();
  const isFocused = useIsFocused();

  const {printerId, webcam} = route.params;

  const selectedWebcam = useSelector( (state) => {
    if (webcam) {
      return webcam;
    }
    const webcams = _.filter(state.printers, {id: printerId})[0]?.settings?.webcams;
    if (webcams && webcams.length === 1) {
      return webcams[0];
    } else {
      return _.find(webcams, {is_primary_camera: true});
    }
  });

  const printer = useSelector(
    (state) => _.filter(state.printers, {id: printerId})[0]
  );
  const webrtcStream = useSelector(
    (state) => state.webrtcStreams[printer.auth_token],
  );

  const userRotationDeg = useSelector((state) => state.preferences?.webcamOpts?.[printerId.toString()]?.[selectedWebcam.name]?.userRotationDeg || 0);

  const [deviceOrientation, setDeviceOrientation] = useState(Orientation.getInitialOrientation());

  const [contextMenuOpen, setContextMenuOpen] = useState(false);
  const [streamingMode, setStreamingMode] = useState('auto');

  useEffect(() => {
    const backHandler = BackHandler.addEventListener('hardwareBackPress', exitFullScreen);
    return () => backHandler.remove();
  }, []);

  useEffect(() => {
    activateKeepAwake();
    return () => {
      deactivateKeepAwake();
    };
  }, []);

  const exitFullScreen = () => {
    console.log('[exitFullScreen]');
    navigation.goBack();
    return true;
  };

  useDeviceOrientationChange((o) => {
    Orientation.getDeviceOrientation((orientation) => {
      const prevOrientation = deviceOrientation;
      console.log('[prevOrientation]: ', prevOrientation);
      console.log('[orientation]: ', orientation);
      if (orientation.includes('LANDSCAPE') || orientation.includes('PORTRAIT')) {
        setDeviceOrientation(orientation);
      }
      if (prevOrientation && prevOrientation.includes('LANDSCAPE') && orientation === 'PORTRAIT'){
        exitFullScreen();
      }
    });
  });

  const rotateBtnPressed = useCallback(() => {
    dispatch(actions.rotateWebcam(printerId, selectedWebcam?.name, 90));
  }, [dispatch, printerId, selectedWebcam?.name]);

  let rotationDeg = userRotationDeg;

  switch (deviceOrientation) {
    case 'LANDSCAPE-LEFT':
      rotationDeg += 90;
      break;
    case 'LANDSCAPE-RIGHT':
      rotationDeg -= 90;
      break;
    default:
      // Full screen mode only support landscape. Force it to be LANDSCAPE-LEFT'
      rotationDeg += 90;
  }

  return (
    <View style={{ backgroundColor: 'black' }} flex={1}>
      <Box safeAreaTop/>
      <View flex={1}>
        <ZoomView>
          <View style={styles.container} colorScheme='surfacePrimary'>
            {
              isFocused &&
              <WebCamView
                printerId={printer.id}
                webcam={selectedWebcam}
                userRotationDeg={rotationDeg}
                deviceOrientation={deviceOrientation}
                showInfoOverlay={true}
              />
            }
          </View>
        </ZoomView>
        <WebCamFullscreenOverlay
          printer={printer}
          deviceOrientation={deviceOrientation}
          onRotate={rotateBtnPressed}
          onClose={exitFullScreen}
          onMenu={() => setContextMenuOpen(true)}
        />
        <ContextMenu
          {...{webrtcStream, contextMenuOpen, setContextMenuOpen, streamingMode, setStreamingMode, exitFullScreen}}
        />
        <Box safeAreaBottom />
      </View>
    </View>
  );
};


const styles = StyleSheet.create({
  container: {
    flex: 1,
    alignItems: 'center',
    padding: 0,
  },
  overlay: {
    width: '100%',
    height: '100%',
    position: 'absolute',
    top: 0,
    left: 0,
  },
  contextMenuButton: {
    position: 'absolute',
    top: 5,
    right: 5,
    zIndex: 1,
    width: 45,
    height: 45
  },
  rotateButton: {
    position: 'absolute',
    top: 5,
    left: 5,
    zIndex: 1,
    width: 70,
    height: 60
  },
  contextMenuIcon: {marginLeft: 10, marginRight: 10, paddingTop: 0},
  mutedStatus: {
    width: '100%',
    position: 'absolute',
    bottom: 0,
    alignItems: 'center',
    paddingVertical: 12,
    marginVertical: 10,
  },
  warning: {
    position: 'absolute',
    top: 15,
    left: 15
  },
  zoomView: {
    flex: 1,
  },
});

export default React.memo(FullScreenWebCam);

