/* eslint-env jest */
import {selectPrimaryWebcam, selectWebcamUserRotationDeg} from '../usePrimaryWebcam';

const stateWith = (webcams, webcamOpts) => ({
  printers: [{id: 1, settings: webcams === undefined ? {} : {webcams}}],
  preferences: {webcamOpts},
});

describe('selectPrimaryWebcam', () => {
  it('returns the only webcam even when it is not marked primary', () => {
    expect(selectPrimaryWebcam(stateWith([{name: 'a'}]), 1)).toEqual({name: 'a'});
  });
  it('returns the webcam marked primary', () => {
    const webcams = [{name: 'a'}, {name: 'b', is_primary_camera: true}];
    expect(selectPrimaryWebcam(stateWith(webcams), 1).name).toBe('b');
  });
  it('returns undefined when the printer reports no webcam', () => {
    expect(selectPrimaryWebcam(stateWith([]), 1)).toBeUndefined();
    expect(selectPrimaryWebcam(stateWith(undefined), 1)).toBeUndefined();
  });
  it('returns undefined for a printer that is not in the store', () => {
    expect(selectPrimaryWebcam(stateWith([{name: 'a'}]), 2)).toBeUndefined();
  });
});

describe('selectWebcamUserRotationDeg', () => {
  const saved = {'1': {a: {userRotationDeg: 90}}};
  it('returns the rotation saved for the webcam', () => {
    expect(selectWebcamUserRotationDeg(stateWith([], saved), 1, {name: 'a'})).toBe(90);
  });
  it('returns 0 when there is no webcam, even with a rotation saved for the printer', () => {
    expect(selectWebcamUserRotationDeg(stateWith([], saved), 1, undefined)).toBe(0);
  });
  it('returns 0 when nothing was saved', () => {
    expect(selectWebcamUserRotationDeg(stateWith([], undefined), 1, {name: 'a'})).toBe(0);
  });
});
EOF
