import _ from 'lodash';
import React, {useEffect, useState, useCallback} from 'react';
import {useSelector, useDispatch} from 'react-redux';
import { StyleSheet, BackHandler } from 'react-native';
import {useRoute, useNavigation} from '@react-navigation/native';
import { View, Box } from 'native-base';
import Orientation, {useDeviceOrientationChange} from 'react-native-orientation-locker';
import { activateKeepAwake, deactivateKeepAwake} from '@sayem314/react-native-keep-awake';

import * as actions from '../../redux/actions';
import {selectPrimaryWebcam, selectWebcamUserRotationDeg} from '../../hooks/usePrimaryWebcam';
import WebCamView from '../../components/WebCamView/WebCamView';
import ZoomView from '../../components/ZoomView/ZoomView';
import ContextMenu from '../../components/WebCamView/ContextMenu';
import WebCamFullscreenOverlay from './WebCamFullscreenOverlay';
import { useIsFocused } from '@react-navigation/native';

const FullScreenWebCam = (props) => {
  const dispatch = useDispatch();
  const route = useRoute();
  const navigation = useNavigation();
  const isFocused = useIsFocused();

  const {printerId, webcam} = route.params;

  const selectedWebcam = useSelector((state) => webcam || selectPrimaryWebcam(state, printerId));

  const printer = useSelector(
    (state) => _.filter(state.printers, {id: printerId})[0]
  );
  const webrtcStream = useSelector(
    (state) => state.webrtcStreams[printer.auth_token],
  );

  const userRotationDeg = useSelector((state) => selectWebcamUserRotationDeg(state, printerId, selectedWebcam));

  const [deviceOrientation, setDeviceOrientation] = useState(Orientation.getInitialOrientation());

  const [contextMenuOpen, setContextMenuOpen] = useState(false);
  const [streamingMode, setStreamingMode] = useState('auto');

  useEffect(() => {
    const backHandler = BackHandler.addEventListener('hardwareBackPress', exitFullScreen);
    return () => backHandler.remove();
  }, []);

  useEffect(() => {
    activateKeepAwake();
    return () => {
      deactivateKeepAwake();
    };
  }, []);

  const exitFullScreen = () => {
    console.log('[exitFullScreen]');
    navigation.goBack();
    return true;
  };

  useDeviceOrientationChange((o) => {
    Orientation.getDeviceOrientation((orientation) => {
      const prevOrientation = deviceOrientation;
      console.log('[prevOrientation]: ', prevOrientation);
      console.log('[orientation]: ', orientation);
      if (orientation.includes('LANDSCAPE') || orientation.includes('PORTRAIT')) {
        setDeviceOrientation(orientation);
      }
      if (prevOrientation && prevOrientation.includes('LANDSCAPE') && orientation === 'PORTRAIT'){
        exitFullScreen();
      }
    });
  });

  const rotateBtnPressed = useCallback(() => {
    dispatch(actions.rotateWebcam(printerId, selectedWebcam?.name, 90));
  }, [dispatch, printerId, selectedWebcam?.name]);

  let rotationDeg = userRotationDeg;

  switch (deviceOrientation) {
    case 'LANDSCAPE-LEFT':
      rotationDeg += 90;
      break;
    case 'LANDSCAPE-RIGHT':
      rotationDeg -= 90;
      break;
    default:
      // Full screen mode only support landscape. Force it to be LANDSCAPE-LEFT'
      rotationDeg += 90;
  }

  return (
    <View style={{ backgroundColor: 'black' }} flex={1}>
      <Box safeAreaTop/>
      <View flex={1}>
        <ZoomView>
          <View style={styles.container} colorScheme='surfacePrimary'>
            {
              isFocused &&
              <WebCamView
                printerId={printer.id}
                webcam={selectedWebcam}
                userRotationDeg={rotationDeg}
                deviceOrientation={deviceOrientation}
                showInfoOverlay={true}
              />
            }
          </View>
        </ZoomView>
        <WebCamFullscreenOverlay
          printer={printer}
          deviceOrientation={deviceOrientation}
          onRotate={rotateBtnPressed}
          onClose={exitFullScreen}
          onMenu={() => setContextMenuOpen(true)}
        />
        <ContextMenu
          {...{webrtcStream, contextMenuOpen, setContextMenuOpen, streamingMode, setStreamingMode, exitFullScreen}}
        />
        <Box safeAreaBottom />
      </View>
    </View>
  );
};


const styles = StyleSheet.create({
  container: {
    flex: 1,
    alignItems: 'center',
    padding: 0,
  },
  overlay: {
    width: '100%',
    height: '100%',
    position: 'absolute',
    top: 0,
    left: 0,
  },
  contextMenuButton: {
    position: 'absolute',
    top: 5,
    right: 5,
    zIndex: 1,
    width: 45,
    height: 45
  },
  rotateButton: {
    position: 'absolute',
    top: 5,
    left: 5,
    zIndex: 1,
    width: 70,
    height: 60
  },
  contextMenuIcon: {marginLeft: 10, marginRight: 10, paddingTop: 0},
  mutedStatus: {
    width: '100%',
    position: 'absolute',
    bottom: 0,
    alignItems: 'center',
    paddingVertical: 12,
    marginVertical: 10,
  },
  warning: {
    position: 'absolute',
    top: 15,
    left: 15
  },
  zoomView: {
    flex: 1,
  },
});

export default React.memo(FullScreenWebCam);

import _ from 'lodash';
import {useSelector} from 'react-redux';

// The webcam a printer shows by default: its only webcam, or the one marked primary.
// Undefined when the printer reports no webcam. moonraker-obico reports an empty list
// when streaming is turned off for every webcam or fails to start, so this is a normal state.
export const selectPrimaryWebcam = (state, printerId) => {
  const webcams = _.find(state.printers, {id: printerId})?.settings?.webcams;
  if (webcams && webcams.length === 1) {
    return webcams[0];
  }
  return _.find(webcams, {is_primary_camera: true});
};

// The rotation the person saved for this webcam in full screen; 0 when there is no webcam
// or no saved rotation. A rotation saved while the printer had a webcam outlives the webcam.
export const selectWebcamUserRotationDeg = (state, printerId, webcam) => {
  if (!webcam) {
    return 0;
  }
  return state.preferences?.webcamOpts?.[printerId.toString()]?.[webcam.name]?.userRotationDeg || 0;
};

// The printer's default webcam and the person's saved rotation for it.
const usePrimaryWebcam = (printerId) => {
  const primaryWebcam = useSelector((state) => selectPrimaryWebcam(state, printerId));
  const userRotationDeg = useSelector((state) => selectWebcamUserRotationDeg(state, printerId, primaryWebcam));
  return {primaryWebcam, userRotationDeg};
};

export default usePrimaryWebcam;

import _ from 'lodash';
import React, {useCallback} from 'react';
import {TouchableOpacity, StyleSheet, Dimensions} from 'react-native';
import WebCamView from '../../components/WebCamView/WebCamView';
import {useIsFocused} from '@react-navigation/native';
import { Heading, View, Text, Progress, Icon, theme } from 'native-base';
import FontAwesome5 from 'react-native-vector-icons/FontAwesome5';
import {P_VALUE_WARNING, P_VALUE_FAILURE} from '../../globals/constants';
import {progressInPct, humanizedDuration, timeFromNow,} from '../../libs/formatter';
import useColors from '../../hooks/useColors';
import { useSelector } from 'react-redux';
import usePrimaryWebcam from '../../hooks/usePrimaryWebcam';
import { useSyndicate } from '@/SyndicateContext';
import { t,Trans } from '@lingui/macro';

const {width, height} = Dimensions.get('window');

const PrinterItem = (props) => {
  const {printerId} = props;

  const printerName = useSelector(state =>
    _.find(state.printers, (p) => p.id === printerId).name);

  // excluding _ts + using memoization (_.isEqual) here prevents `printerStatus` to be frequently
  // updated and as a result saves this component from bunch of unnecessary re-renderings
  const printerStatus = useSelector(state => {
    const status = _.find(state.printers, (p) => p.id === printerId).status;
    return { ...status, _ts: null };
  }, _.isEqual);

  const progress = printerStatus?.progress?.completion || 0;
  const printTimeLeft = printerStatus?.progress?.printTimeLeft;
  const statusText = printerStatus?.state?.text;

  const derivedStatus = useSelector(state =>
    _.find(state.printers, (p) => p.id === printerId).derivedStatus);

  const normalizedP = useSelector(state => _.find(state.printers, (p) => p.id === printerId).normalized_p || 0);

  const {primaryWebcam, userRotationDeg: webcamUserRotationDeg} = usePrimaryWebcam(printerId);

  const isFocused = useIsFocused();
  const thumbnailViewSize = width < height ? width : height;

  const {color} = useColors();
  const watchingStatusColorScheme = () => {
    if (derivedStatus.isWatching) {
      if (normalizedP > P_VALUE_FAILURE) {
        return 'danger';
      } else if (normalizedP > P_VALUE_WARNING) {
        return 'warning';
      } else {
        return 'success';
      }
    }
    return 'muted';
  };

  const renderPrinterStatus = useCallback(() => {

    if (derivedStatus.isOffline) {
      return (
        <View flex="2"><Text colorScheme='warning'><Trans>Obico Plugin is Offline</Trans></Text></View>
      );
    }
    if (derivedStatus.isDisconnected) {
      return (
        <View flex="2"><Text colorScheme='warning'> {t`Printer not connected at the serial port`}</Text></View>
      );
    }
    if (statusText) {
      return (
        <View flex="2"><Text colorScheme='success'>{derivedStatus.calculatedState}</Text></View>
      );
    }
    return <></>;
  }, [derivedStatus, statusText]);

  return (
    <TouchableOpacity
      style={{
        ...styles.mainView,
        backgroundColor: color('surfacePrimary'),
      }}
      onPress={() => props.onPress(printerId)}
    >
      {isFocused && primaryWebcam && (
        <View
          style={{
            ...styles.thumbnailView,
            width: thumbnailViewSize * 0.33,
            minHeight: thumbnailViewSize * 0.33,
          }}>
          <WebCamView
            printerId={printerId}
            webcam={primaryWebcam}
            showInfoOverlay={false}
            userRotationDeg={webcamUserRotationDeg}
          />
        </View>
      )}
      <View style={styles.infoView}>
        <View style={styles.titleView}>
          <Heading size='h4' ellipsizeMode='middle' numberOfLines={1} bold flex={1}>
            {printerName}
            {' '}
          </Heading>
          <Text pt={Platform.OS === 'android' ? 2 : 0} pr={1}>
            <Icon
              as={FontAwesome5}
              name={derivedStatus.isWatching ? 'eye' : 'eye-slash'}
              size='xs'
              pr={4}
              colorScheme={watchingStatusColorScheme()}
            />
          </Text>
        </View>
        {!(derivedStatus.isActive) && renderPrinterStatus()}
        {derivedStatus.isActive && (
          <View>
            <Text ellipsizeMode='middle' numberOfLines={1}>{printerStatus?.job?.file?.name || ''}</Text>
            <View style={styles.progressInfo}>
              <View variant="inline" flexWrap="wrap" flex="1" mr="1" alignItems='center'>
                <View variant="inline" alignItems='center'>
                  <Icon
                    as={FontAwesome5}
                    name="stopwatch"
                    size='xxs'
                    colorScheme='muted'
                    mr='1'
                  />
                  <Text mr='2'>{humanizedDuration(printTimeLeft)}</Text>
                </View>
                <View variant="inline" alignItems='center'>
                  <Icon
                    as={FontAwesome5}
                    name="flag-checkered"
                    size='xxs'
                    colorScheme='muted'
                    mr='1'
                  />
                  <Text>{timeFromNow(printTimeLeft)}</Text>
                </View>
              </View>
              <Text fontSize="h4" bold>{progressInPct(progress)}</Text>
            </View>
            <Progress
              value={progress}
              size='sm'
            />
          </View>
        )}
      </View>
    </TouchableOpacity>
  );
};

const styles = StyleSheet.create({
  mainView: {
    borderRadius: 10,
    flexDirection: 'row',
    marginBottom: theme.space['4'],
    overflow: 'hidden',
  },
  thumbnailView: {
    overflow: 'hidden',
  },
  infoView: {
    flex: 1,
    padding: 12,
    justifyContent: 'space-between',
  },
  titleView: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 5,
  },
  progressInfo: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'flex-end',
    marginTop: 8,
    marginBottom: 4,
  },
});

export default React.memo(PrinterItem);

