#!/usr/bin/env python3
"""PreToolUse hook for Bash: ask Kenneth before an agent resolves a Sentry issue
without "next release".

A plain {"status": "resolved"} stays resolved only until the next event, and
"resolved in release X" reopens on X's own events. Kenneth wants fixed issues
resolved with {"status":"resolved","statusDetails":{"inNextRelease":true}} (or
the "resolvedInNextRelease" status). Any other resolve gets a confirmation prompt.

The check reads the command text plus any file passed to curl as @file data.
It looks for a PUT that mentions Sentry and sets status to resolved, with no
inNextRelease anywhere. Anything it cannot parse is let through unchanged.
"""
import json
import os
import re
import sys

RESOLVE = re.compile(r"""status[\\"']*\s*[:=]\s*[\\"']*resolved\b""")
DATA_FILE = re.compile(r"""(?:-d|--data(?:-binary|-raw|-urlencode)?)[=\s]+['"]?@([^\s'"]+)""")


def main():
    try:
        payload = json.load(sys.stdin)
    except Exception:
        return
    command = (payload.get("tool_input") or {}).get("command") or ""
    text = command
    for path in DATA_FILE.findall(command):
        try:
            with open(os.path.expanduser(path), encoding="utf-8", errors="replace") as f:
                text += "\n" + f.read(200_000)
        except OSError:
            pass

    if "sentry" not in text.lower():
        return
    if "PUT" not in text and ".put(" not in text:
        return
    if not RESOLVE.search(text):
        return
    if "inNextRelease" in text:
        return

    reason = (
        "This command resolves a Sentry issue without \"next release\". "
        "A plain resolve, or \"resolved in release X\", reopens on events from the "
        "release that is live now. Fixed issues should use "
        "{\"status\":\"resolved\",\"statusDetails\":{\"inNextRelease\":true}}. "
        "Allow it only if a plain resolve is really what you want, such as a "
        "one-off test issue."
    )
    print(json.dumps({
        "hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": "ask",
            "permissionDecisionReason": reason,
        }
    }))


if __name__ == "__main__":
    main()

