import json
e=json.load(open("/tmp/claude/claude-502/-Users-kenneth-Projects-claude-cowork-wd/e72a2155-9484-4e5d-89d6-fcf6b8d253be/scratchpad/5p.json"))
print("tags",[(t["key"],t["value"]) for t in e["tags"] if t["key"] in ("release","os","device","os.name","dist","environment")])
ctx=e.get("contexts",{})
print("app",ctx.get("app",{}).get("app_start_time"),ctx.get("app",{}).get("app_version"),ctx.get("app",{}).get("in_foreground"))
for en in e["entries"]:
    if en["type"]=="threads":
        for t in en["data"]["values"]:
            if t.get("crashed") or t.get("current") or t.get("id")==0:
                fr=(t.get("stacktrace") or {}).get("frames",[])
                print("thread",t.get("id"),t.get("name"))
                for f in fr[::-1][:25]:
                    print("  ",f.get("package","").split("/")[-1] if f.get("package") else "",f.get("function"),"inApp" if f.get("inApp") else "")
    if en["type"]=="exception":
        for v in en["data"]["values"]:
            print("exc",v["type"],v["value"])
            fr=(v.get("stacktrace") or {}).get("frames",[])
            for f in fr[::-1][:30]:
                print("  ",(f.get("package") or "").split("/")[-1],f.get("function"),"inApp" if f.get("inApp") else "")
    if en["type"]=="breadcrumbs":
        for b in en["data"]["values"][-12:]:
            print("bc",b.get("timestamp"),b.get("category"),(b.get("message") or "")[:100])
EOF

