    _preferences = await _preferencesLoader();
    _attribution = _readAttribution(_preferences!);
    if (!_enabled) return;

    if (_singularApiKey.isEmpty || _singularApiSecret.isEmpty) {
      debugPrint('[Acquisition] Singular SDK credentials are missing');
      return;
    }

    final resolution = Completer<void>();
    final config = SingularConfig(_singularApiKey, _singularApiSecret)
      ..clipboardAttribution = false
      ..enableLogging = false
      ..shortLinkResolveTimeOut = _resolutionTimeout.inMilliseconds / 1000
      ..singularLinksHandler = (params) {
        unawaited(_handleSingularLink(params).whenComplete(() {
          if (!resolution.isCompleted) resolution.complete();
        }));
      };

    try {
      _singularStarter(config);
    } catch (error, stackTrace) {
      debugPrint('[Acquisition] Singular initialization failed: $error');
      debugPrint('$stackTrace');
      return;
    }
