open("/tmp/claude/claude-502/-Users-kenneth-Projects-claude-cowork-wd/e72a2155-9484-4e5d-89d6-fcf6b8d253be/scratchpad/m_id","w").write(g["id"])'
ID=$(cat $S/m_id); curl -s -H "Authorization: Bearer $TOKEN" "$B/issues/$ID/events/latest/" > $S/m.json; curl -s -H "Authorization: Bearer $TOKEN" "$B/issues/$ID/comments/" | python3 -c 'import json,sys;[print("NOTE",c["dateCreated"][:10],c["data"]["text"][:1200]) for c in json.load(sys.stdin)]'
python3 - <<'EOF'
import json
e=json.load(open("/tmp/claude/claude-502/-Users-kenneth-Projects-claude-cowork-wd/e72a2155-9484-4e5d-89d6-fcf6b8d253be/scratchpad/m.json"))
print("tags",[(t["key"],t["value"]) for t in e["tags"] if t["key"] in ("release","os","os.name","level","handled","mechanism","environment")])
print("msg",(e.get("message") or "")[:300])
for en in e["entries"]:
    if en["type"]=="exception":
        for v in en["data"]["values"]:
            print("exc",v["type"],"|",(v["value"] or "")[:400], v.get("mechanism"))
            for f in (v.get("stacktrace") or {}).get("frames",[])[::-1][:40]:
                print("  ",(f.get("package") or "").split("\\")[-1].split("/")[-1],f.get("function"),(f.get("filename") or "").split("\\")[-1].split("/")[-1],f.get("lineNo"),"inApp" if f.get("inApp") else "")
    if en["type"]=="threads":
        for t in en["data"]["values"]:
            if t.get("crashed"):
                print("crashed thread",t.get("id"))
                for f in (t.get("stacktrace") or {}).get("frames",[])[::-1][:40]:
                    print("  ",(f.get("package") or "").split("\\")[-1],f.get("function"),(f.get("filename") or "").split("\\")[-1],f.get("lineNo"))
    if en["type"]=="breadcrumbs":
        for b in en["data"]["values"][-15:]:
            print("bc",b.get("timestamp"),b.get("category"),(b.get("message") or json.dumps(b.get("data")) or "")[:160])
EOF

